sketch matmul_transpose {
  symbols: M, N, K;
  tensors: A[K, M]: f32; B[N, K]: f32; C[M, N]: f32;
  constexpr: BM, BN, BK;

  @llm_hint("parallel", "grididx.x")
  for i in range(0, M, BM):
    @llm_hint("parallel", "grididx.y")
    for j in range(0, N, BN):
      a_tile = alloc([BM, BK], llm_hint=["fast", "input_cache"])
      b_tile = alloc([BK, BN], llm_hint=["fast", "input_cache"])
      acc = alloc([BM, BN], llm_hint=["fastest", "accumulator", "init_zero"])
      @llm_hint("pipeline")
      for k in range(0, K, BK):
        # 索引计算
        # i_idx = i + arange(BM)  # 形状 [BM]，对应 A 的第二维 (M 维度)
        # k_idx = k + arange(BK)  # 形状 [BK]，对应 A 的第一维 (K 维度)
        # mask_a: 确保 k_idx 在 [0, K) 和 i_idx 在 [0, M) 内，通过 & 组合边界条件
        load(A[k_idx, i_idx] -> a_tile, mask=mask_a, llm_hint=["cooperative_load", "vectorized"])
        # j_idx = j + arange(BN)  # 形状 [BN]，对应 B 的第一维 (N 维度)
        # k_idx = k + arange(BK)  # 形状 [BK]，对应 B 的第二维 (K 维度)
        # mask_b: 确保 j_idx 在 [0, N) 和 k_idx 在 [0, K) 内
        load(B[j_idx, k_idx] -> b_tile, mask=mask_b, llm_hint=["cooperative_load", "vectorized"])
        gemm(a_tile, b_tile, acc)
      # store 索引
      # i_idx = i + arange(BM)  # 形状 [BM]，对应 C 的第一维 (M 维度)
      # j_idx = j + arange(BN)  # 形状 [BN]，对应 C 的第二维 (N 维度)
      # mask_store: 确保 i_idx 在 [0, M) 和 j_idx 在 [0, N) 内
      store(acc -> C[i_idx, j_idx], mask=mask_store, llm_hint=["cooperative_store", "vectorized"])
}

