sketch Matmul_with_transposed_both {
  symbols: M, N, K;
  tensors: A[K, M]: f16; B[N, K]: f16; C[M, N]: f32;
  constexpr: BM, BN, BK;

  @llm_hint("parallel", "grididx.x")
  for i in range(0, M, BM):
    @llm_hint("parallel", "grididx.y")
    for j in range(0, N, BN):
      a_tile = alloc([BM, BK], llm_hint=["fast", "input_cache"])
      b_tile = alloc([BK, BN], llm_hint=["fast", "input_cache"])
      acc = alloc([BM, BN], llm_hint=["fastest", "accumulator", "init_zero"])

      @llm_hint("pipeline")
      for k in range(0, K, BK):
        a_k_idx = k + arange(0, BK) & (k + arange(0, BK) < K)
        a_i_idx = i + arange(0, BM) & (i + arange(0, BM) < M)
        b_k_idx = k + arange(0, BK) & (k + arange(0, BK) < K)
        b_j_idx = j + arange(0, BN) & (j + arange(0, BN) < N)

        mask_a = (a_k_idx < K) & (a_i_idx < M)
        mask_b = (b_k_idx < K) & (b_j_idx < N)

        load(A[a_k_idx, a_i_idx] -> a_tile, mask=mask_a, llm_hint=["cooperative_load", "vectorized"])
        load(B[b_j_idx, b_k_idx] -> b_tile, mask=mask_b, llm_hint=["cooperative_load", "vectorized"])
        gemm(a_tile, b_tile, acc)

      c_i_idx = i + arange(0, BM) & (i + arange(0, BM) < M)
      c_j_idx = j + arange(0, BN) & (j + arange(0, BN) < N)
      mask_store = (c_i_idx < M) & (c_j_idx < N)

      store(acc -> C[c_i_idx, c_j_idx], mask=mask_store, llm_hint=["cooperative_store"])
}
